CREATE FUNCTION public.drive_resolution_requeue() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.state='applied' AND OLD.state<>NEW.state AND NEW.folder_snapshot->>'entityType'='record' THEN UPDATE public.campaign_records SET sync_state='pending' WHERE id=(NEW.folder_snapshot->>'id')::uuid; UPDATE public.sync_outbox SET state='pending',next_attempt_at=now(),error=NULL WHERE entity_type='record' AND entity_id=(NEW.folder_snapshot->>'id')::uuid; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.drive_resolution_requeue() FROM PUBLIC,anon,authenticated; CREATE TRIGGER drive_resolution_enqueue AFTER UPDATE OF state ON public.drive_sync_inbox FOR EACH ROW EXECUTE FUNCTION public.drive_resolution_requeue();